// PDF Master Pro - Input Component
import React, { useState } from 'react';
import {
  View,
  TextInput,
  Text,
  StyleSheet,
  TouchableOpacity,
  ViewStyle,
  TextStyle,
  TextInputProps,
} from 'react-native';
import { useTheme } from '../../context';
import { BorderRadius, Layout, Typography, Spacing } from '../../constants/theme';

interface InputProps extends TextInputProps {
  label?: string;
  error?: string;
  hint?: string;
  leftIcon?: React.ReactNode;
  rightIcon?: React.ReactNode;
  onRightIconPress?: () => void;
  containerStyle?: ViewStyle;
  inputStyle?: TextStyle;
}

export const Input: React.FC<InputProps> = ({
  label,
  error,
  hint,
  leftIcon,
  rightIcon,
  onRightIconPress,
  containerStyle,
  inputStyle,
  secureTextEntry,
  ...props
}) => {
  const { colors, isDark } = useTheme();
  const [isFocused, setIsFocused] = useState(false);
  const [isPasswordVisible, setIsPasswordVisible] = useState(false);

  const isPassword = secureTextEntry !== undefined;
  const showPassword = isPassword && isPasswordVisible;

  const getBorderColor = () => {
    if (error) return colors.error;
    if (isFocused) return colors.primary;
    return colors.border;
  };

  return (
    <View style={[styles.container, containerStyle]}>
      {label && (
        <Text style={[styles.label, { color: colors.textPrimary }]}>{label}</Text>
      )}

      <View
        style={[
          styles.inputContainer,
          {
            borderColor: getBorderColor(),
            backgroundColor: colors.bgWhite,
          },
        ]}
      >
        {leftIcon && <View style={styles.leftIcon}>{leftIcon}</View>}

        <TextInput
          {...props}
          style={[
            styles.input,
            {
              color: colors.textPrimary,
              paddingLeft: leftIcon ? 0 : Spacing.md,
              paddingRight: rightIcon || isPassword ? 0 : Spacing.md,
            },
            inputStyle,
          ]}
          placeholderTextColor={colors.textLight}
          secureTextEntry={isPassword && !showPassword}
          onFocus={() => setIsFocused(true)}
          onBlur={() => setIsFocused(false)}
        />

        {isPassword && (
          <TouchableOpacity
            style={styles.rightIcon}
            onPress={() => setIsPasswordVisible(!isPasswordVisible)}
          >
            <Text style={{ color: colors.textSecondary }}>
              {showPassword ? 'Hide' : 'Show'}
            </Text>
          </TouchableOpacity>
        )}

        {rightIcon && !isPassword && (
          <TouchableOpacity
            style={styles.rightIcon}
            onPress={onRightIconPress}
            disabled={!onRightIconPress}
          >
            {rightIcon}
          </TouchableOpacity>
        )}
      </View>

      {error && <Text style={[styles.error, { color: colors.error }]}>{error}</Text>}
      {hint && !error && (
        <Text style={[styles.hint, { color: colors.textSecondary }]}>{hint}</Text>
      )}
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    marginBottom: Spacing.md,
  },
  label: {
    fontSize: Typography.fontSize.sm,
    fontWeight: Typography.fontWeight.medium,
    marginBottom: Spacing.xs,
  },
  inputContainer: {
    flexDirection: 'row',
    alignItems: 'center',
    height: Layout.inputHeight,
    borderWidth: 1.5,
    borderRadius: BorderRadius.md,
  },
  input: {
    flex: 1,
    height: '100%',
    fontSize: Typography.fontSize.base,
  },
  leftIcon: {
    paddingLeft: Spacing.md,
    paddingRight: Spacing.sm,
  },
  rightIcon: {
    paddingHorizontal: Spacing.md,
    height: '100%',
    justifyContent: 'center',
  },
  error: {
    fontSize: Typography.fontSize.xs,
    marginTop: Spacing.xs,
  },
  hint: {
    fontSize: Typography.fontSize.xs,
    marginTop: Spacing.xs,
  },
});

export default Input;

// PDF Master Pro - Loading Component
import React from 'react';
import { View, ActivityIndicator, Text, StyleSheet, Modal } from 'react-native';
import { useTheme } from '../../context';
import { Typography, Spacing, BorderRadius } from '../../constants/theme';

interface LoadingProps {
  visible?: boolean;
  message?: string;
  overlay?: boolean;
  size?: 'small' | 'large';
}

export const Loading: React.FC<LoadingProps> = ({
  visible = true,
  message,
  overlay = false,
  size = 'large',
}) => {
  const { colors } = useTheme();

  const content = (
    <View
      style={[
        styles.container,
        overlay && styles.overlay,
        { backgroundColor: overlay ? 'rgba(0,0,0,0.5)' : 'transparent' },
      ]}
    >
      <View
        style={[
          styles.content,
          overlay && styles.overlayContent,
          overlay && { backgroundColor: colors.bgWhite },
        ]}
      >
        <ActivityIndicator size={size} color={colors.primary} />
        {message && (
          <Text style={[styles.message, { color: colors.textPrimary }]}>
            {message}
          </Text>
        )}
      </View>
    </View>
  );

  if (!visible) return null;

  if (overlay) {
    return (
      <Modal transparent visible={visible} animationType="fade">
        {content}
      </Modal>
    );
  }

  return content;
};

// Inline Loading Spinner
export const LoadingSpinner: React.FC<{ color?: string; size?: 'small' | 'large' }> = ({
  color,
  size = 'small',
}) => {
  const { colors } = useTheme();
  return <ActivityIndicator size={size} color={color || colors.primary} />;
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
  },
  overlay: {
    position: 'absolute',
    top: 0,
    left: 0,
    right: 0,
    bottom: 0,
  },
  content: {
    alignItems: 'center',
    justifyContent: 'center',
  },
  overlayContent: {
    padding: Spacing.xl,
    borderRadius: BorderRadius.lg,
    minWidth: 120,
  },
  message: {
    marginTop: Spacing.md,
    fontSize: Typography.fontSize.base,
    fontWeight: Typography.fontWeight.medium,
    textAlign: 'center',
  },
});

export default Loading;

// PDF Master Pro - Storage Context
import React, { createContext, useContext, useState, useEffect, useCallback, ReactNode } from 'react';
import RNFS from 'react-native-fs';
import { StorageInfo, PLAN_CONFIG } from '../types/subscription';
import { useSubscription } from './SubscriptionContext';

interface StorageContextType {
  storageInfo: StorageInfo;
  isLoading: boolean;
  refreshStorage: () => Promise<void>;
  canSaveFile: (fileSizeBytes: number) => boolean;
  getAvailableSpace: () => number;
  formatBytes: (bytes: number) => string;
  deleteFile: (filePath: string) => Promise<boolean>;
}

const StorageContext = createContext<StorageContextType | undefined>(undefined);

interface StorageProviderProps {
  children: ReactNode;
}

// App documents directory for storing PDFs
const APP_DOCUMENTS_DIR = `${RNFS.DocumentDirectoryPath}/PDFMasterPro`;

export const StorageProvider: React.FC<StorageProviderProps> = ({ children }) => {
  const { isPro, storageLimit } = useSubscription();
  const [storageInfo, setStorageInfo] = useState<StorageInfo>({
    usedBytes: 0,
    limitBytes: PLAN_CONFIG.free.storageLimitBytes,
    isLimitReached: false,
  });
  const [isLoading, setIsLoading] = useState(true);

  // Calculate total size of files in app directory
  const calculateUsedStorage = useCallback(async (): Promise<number> => {
    try {
      // Ensure directory exists
      const dirExists = await RNFS.exists(APP_DOCUMENTS_DIR);
      if (!dirExists) {
        await RNFS.mkdir(APP_DOCUMENTS_DIR);
        return 0;
      }

      // Get all files recursively
      const files = await RNFS.readDir(APP_DOCUMENTS_DIR);
      let totalSize = 0;

      for (const file of files) {
        if (file.isFile()) {
          totalSize += file.size;
        } else if (file.isDirectory()) {
          // Recursively calculate subdirectory size
          totalSize += await calculateDirectorySize(file.path);
        }
      }

      return totalSize;
    } catch (error) {
      console.error('Error calculating storage:', error);
      return 0;
    }
  }, []);

  // Helper to calculate directory size recursively
  const calculateDirectorySize = async (dirPath: string): Promise<number> => {
    try {
      const files = await RNFS.readDir(dirPath);
      let size = 0;

      for (const file of files) {
        if (file.isFile()) {
          size += file.size;
        } else if (file.isDirectory()) {
          size += await calculateDirectorySize(file.path);
        }
      }

      return size;
    } catch (error) {
      console.error('Error calculating directory size:', error);
      return 0;
    }
  };

  // Refresh storage info
  const refreshStorage = useCallback(async (): Promise<void> => {
    setIsLoading(true);
    try {
      const usedBytes = await calculateUsedStorage();
      const limitBytes = isPro ? -1 : PLAN_CONFIG.free.storageLimitBytes;
      const isLimitReached = !isPro && usedBytes >= limitBytes;

      setStorageInfo({
        usedBytes,
        limitBytes,
        isLimitReached,
      });
    } catch (error) {
      console.error('Error refreshing storage:', error);
    } finally {
      setIsLoading(false);
    }
  }, [isPro, calculateUsedStorage]);

  // Check if a file can be saved
  const canSaveFile = useCallback(
    (fileSizeBytes: number): boolean => {
      // Pro users have unlimited storage
      if (isPro) return true;

      const newTotal = storageInfo.usedBytes + fileSizeBytes;
      return newTotal <= PLAN_CONFIG.free.storageLimitBytes;
    },
    [isPro, storageInfo.usedBytes]
  );

  // Get available space in bytes
  const getAvailableSpace = useCallback((): number => {
    // Pro users have unlimited storage
    if (isPro) return -1;

    const available = PLAN_CONFIG.free.storageLimitBytes - storageInfo.usedBytes;
    return Math.max(0, available);
  }, [isPro, storageInfo.usedBytes]);

  // Format bytes to human-readable string
  const formatBytes = useCallback((bytes: number): string => {
    if (bytes === -1) return 'Unlimited';
    if (bytes === 0) return '0 B';

    const k = 1024;
    const sizes = ['B', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));

    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  }, []);

  // Delete a file and refresh storage
  const deleteFile = useCallback(
    async (filePath: string): Promise<boolean> => {
      try {
        const exists = await RNFS.exists(filePath);
        if (exists) {
          await RNFS.unlink(filePath);
          await refreshStorage();
          return true;
        }
        return false;
      } catch (error) {
        console.error('Error deleting file:', error);
        return false;
      }
    },
    [refreshStorage]
  );

  // Initial load and refresh when isPro changes
  useEffect(() => {
    refreshStorage();
  }, [refreshStorage]);

  const value: StorageContextType = {
    storageInfo,
    isLoading,
    refreshStorage,
    canSaveFile,
    getAvailableSpace,
    formatBytes,
    deleteFile,
  };

  return (
    <StorageContext.Provider value={value}>
      {children}
    </StorageContext.Provider>
  );
};

export const useStorage = (): StorageContextType => {
  const context = useContext(StorageContext);
  if (context === undefined) {
    throw new Error('useStorage must be used within a StorageProvider');
  }
  return context;
};

// Export the app documents directory path for use in other parts of the app
export const getAppDocumentsDir = (): string => APP_DOCUMENTS_DIR;

export default StorageContext;

// PDF Master Pro - Main Navigator (Bottom Tabs)
import React from 'react';
import { StyleSheet, View, Text } from 'react-native';
import { createBottomTabNavigator } from '@react-navigation/bottom-tabs';
import { createNativeStackNavigator } from '@react-navigation/native-stack';
import { MainTabParamList, ToolStackParamList, RootStackParamList } from '../types/navigation';
import { useTheme, useLanguage } from '../context';
import { Layout, Typography } from '../constants/theme';

// Main Screens
import HomeScreen from '../screens/main/HomeScreen';
import ToolsScreen from '../screens/main/ToolsScreen';
import SettingsScreen from '../screens/main/SettingsScreen';
import ProfileScreen from '../screens/main/ProfileScreen';
import SubscriptionScreen from '../screens/main/SubscriptionScreen';
import DocumentsScreen from '../screens/pages/DocumentsScreen';
import FavoritesScreen from '../screens/pages/FavoritesScreen';

// Tool Screens
import MergeScreen from '../screens/tools/MergeScreen';
import SplitScreen from '../screens/tools/SplitScreen';
import CompressScreen from '../screens/tools/CompressScreen';
import RotateScreen from '../screens/tools/RotateScreen';
import ProtectScreen from '../screens/tools/ProtectScreen';
import UnlockScreen from '../screens/tools/UnlockScreen';
import WatermarkScreen from '../screens/tools/WatermarkScreen';
import PageNumbersScreen from '../screens/tools/PageNumbersScreen';
import OCRScreen from '../screens/tools/OCRScreen';
import OrganizeScreen from '../screens/tools/OrganizeScreen';

const Tab = createBottomTabNavigator<MainTabParamList>();
const ToolStack = createNativeStackNavigator<ToolStackParamList>();
const MainStack = createNativeStackNavigator();

// Tool Stack Navigator
const ToolsStackNavigator: React.FC = () => {
  return (
    <ToolStack.Navigator
      screenOptions={{
        headerShown: false,
        animation: 'slide_from_right',
      }}
    >
      <ToolStack.Screen name="ToolsList" component={ToolsScreen} />
      <ToolStack.Screen name="Merge" component={MergeScreen} />
      <ToolStack.Screen name="Split" component={SplitScreen} />
      <ToolStack.Screen name="Compress" component={CompressScreen} />
      <ToolStack.Screen name="Rotate" component={RotateScreen} />
      <ToolStack.Screen name="Protect" component={ProtectScreen} />
      <ToolStack.Screen name="Unlock" component={UnlockScreen} />
      <ToolStack.Screen name="Watermark" component={WatermarkScreen} />
      <ToolStack.Screen name="PageNumbers" component={PageNumbersScreen} />
      <ToolStack.Screen name="OCR" component={OCRScreen} />
      <ToolStack.Screen name="Organize" component={OrganizeScreen} />
    </ToolStack.Navigator>
  );
};

// Tab Icon Component
const TabIcon: React.FC<{ name: string; focused: boolean; color: string }> = ({
  name,
  focused,
  color,
}) => {
  const iconMap: Record<string, string> = {
    Home: '🏠',
    Documents: '📁',
    Tools: '🔧',
    Favorites: '⭐',
    Settings: '⚙️',
  };

  return (
    <Text style={{ fontSize: focused ? 24 : 22 }}>
      {iconMap[name] || '📄'}
    </Text>
  );
};

// Tab Navigator Component
const TabNavigator: React.FC = () => {
  const { colors } = useTheme();
  const { t } = useLanguage();

  return (
    <Tab.Navigator
      screenOptions={({ route }) => ({
        headerShown: false,
        tabBarIcon: ({ focused, color }) => (
          <TabIcon name={route.name} focused={focused} color={color} />
        ),
        tabBarActiveTintColor: colors.primary,
        tabBarInactiveTintColor: colors.textSecondary,
        tabBarStyle: {
          backgroundColor: colors.bgWhite,
          borderTopColor: colors.border,
          height: Layout.tabBarHeight,
          paddingBottom: 8,
          paddingTop: 8,
        },
        tabBarLabelStyle: {
          fontSize: Typography.fontSize.xs,
          fontWeight: Typography.fontWeight.medium,
        },
      })}
    >
      <Tab.Screen
        name="Home"
        component={HomeScreen}
        options={{ tabBarLabel: t.home.welcomeBack.split('!')[0] || 'Home' }}
      />
      <Tab.Screen
        name="Documents"
        component={DocumentsScreen}
        options={{ tabBarLabel: t.documents.title }}
      />
      <Tab.Screen
        name="Tools"
        component={ToolsStackNavigator}
        options={{ tabBarLabel: t.tools.allTools }}
      />
      <Tab.Screen
        name="Favorites"
        component={FavoritesScreen}
        options={{ tabBarLabel: t.favorites.title }}
      />
      <Tab.Screen
        name="Settings"
        component={SettingsScreen}
        options={{ tabBarLabel: t.settings.title }}
      />
    </Tab.Navigator>
  );
};

// Main Navigator with Profile Screen
export const MainNavigator: React.FC = () => {
  return (
    <MainStack.Navigator
      screenOptions={{
        headerShown: false,
        animation: 'slide_from_right',
      }}
    >
      <MainStack.Screen name="MainTabs" component={TabNavigator} />
      <MainStack.Screen
        name="Profile"
        component={ProfileScreen}
        options={{
          animation: 'slide_from_bottom',
        }}
      />
      <MainStack.Screen
        name="Subscription"
        component={SubscriptionScreen}
        options={{
          animation: 'slide_from_bottom',
        }}
      />
    </MainStack.Navigator>
  );
};

export default MainNavigator;

// PDF Master Pro - Login Screen
import React, { useState } from 'react';
import {
  View,
  Text,
  StyleSheet,
  TouchableOpacity,
  KeyboardAvoidingView,
  Platform,
  ScrollView,
  Alert,
} from 'react-native';
import { useNavigation } from '@react-navigation/native';
import { NativeStackNavigationProp } from '@react-navigation/native-stack';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { AuthStackParamList } from '../../types/navigation';
import { useTheme, useLanguage, useAuth } from '../../context';
import { Button, Input, Header } from '../../components/common';
import { Typography, Spacing, BorderRadius } from '../../constants/theme';

type LoginNavigationProp = NativeStackNavigationProp<AuthStackParamList, 'Login'>;

const LoginScreen: React.FC = () => {
  const navigation = useNavigation<LoginNavigationProp>();
  const { colors } = useTheme();
  const { t } = useLanguage();
  const { login, googleSignIn, appleSignIn, isLoading, error } = useAuth();
  const insets = useSafeAreaInsets();

  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [errors, setErrors] = useState<{ email?: string; password?: string }>({});

  const validate = (): boolean => {
    const newErrors: { email?: string; password?: string } = {};

    if (!email.trim()) {
      newErrors.email = t.auth.emailRequired;
    } else if (!/\S+@\S+\.\S+/.test(email)) {
      newErrors.email = t.auth.invalidEmail;
    }

    if (!password) {
      newErrors.password = t.auth.passwordRequired;
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleLogin = async () => {
    if (!validate()) return;

    try {
      await login({ email, password });
      // Navigation will be handled by AppNavigator
    } catch (err: any) {
      Alert.alert(t.common.error, err.message || t.errors.loginFailed);
    }
  };

  const handleGoogleSignIn = async () => {
    try {
      await googleSignIn();
    } catch (err: any) {
      Alert.alert(t.common.error, err.message || t.errors.loginFailed);
    }
  };

  const handleAppleSignIn = async () => {
    try {
