// PDF Master Pro - Settings Screen
import React, { useState } from 'react';
import {
  View,
  Text,
  StyleSheet,
  ScrollView,
  TouchableOpacity,
  Switch,
  Alert,
} from 'react-native';
import { useNavigation } from '@react-navigation/native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { useTheme, useLanguage, useAuth, useSubscription, useStorage } from '../../context';
import { Card } from '../../components/common';
import { Typography, Spacing, BorderRadius } from '../../constants/theme';
import { LANGUAGES } from '../../constants/config';
import { LanguageCode } from '../../i18n';

const SettingsScreen: React.FC = () => {
  const navigation = useNavigation<any>();
  const { colors, isDark, toggleTheme } = useTheme();
  const { t, language, setLanguage, isRTL } = useLanguage();
  const { user, logout } = useAuth();
  const { storageLimit, isPro } = useSubscription();
  const { storageInfo } = useStorage();
  const insets = useSafeAreaInsets();

  const [notifications, setNotifications] = useState(true);

  // Calculate storage display values
  const usedMB = (storageInfo.usedBytes / (1024 * 1024)).toFixed(1);
  const limitMB = storageLimit === -1 ? '∞' : (storageLimit / (1024 * 1024)).toFixed(0);
  const usagePercent = storageLimit === -1 ? 0 : Math.min((storageInfo.usedBytes / storageLimit) * 100, 100);

  const handleLogout = () => {
    Alert.alert(
      t.auth.logout,
      'Are you sure you want to logout?',
      [
        { text: t.common.cancel, style: 'cancel' },
        {
          text: t.auth.logout,
          style: 'destructive',
          onPress: async () => {
            try {
              await logout();
            } catch (error) {
              console.error('Logout error:', error);
            }
          },
        },
      ]
    );
  };

  const handleLanguageChange = () => {
    Alert.alert(
      t.settings.language,
      'Select your preferred language',
      LANGUAGES.map((lang) => ({
        text: `${lang.flag} ${lang.nativeName}`,
        onPress: () => setLanguage(lang.code as LanguageCode),
      }))
    );
  };

  const handleClearCache = () => {
    Alert.alert(
      t.settings.clearCache,
      'Are you sure you want to clear all cached data?',
      [
        { text: t.common.cancel, style: 'cancel' },
        {
          text: t.common.confirm,
          onPress: () => {
            // TODO: Clear cache
            Alert.alert(t.common.success, t.settings.cacheCleared);
          },
        },
      ]
    );
  };

  const SettingsItem: React.FC<{
    icon: string;
    title: string;
    value?: string;
    onPress?: () => void;
    rightComponent?: React.ReactNode;
    showArrow?: boolean;
  }> = ({ icon, title, value, onPress, rightComponent, showArrow = true }) => (
    <TouchableOpacity
      style={styles.settingsItem}
      onPress={onPress}
      disabled={!onPress}
      activeOpacity={onPress ? 0.7 : 1}
    >
      <Text style={styles.settingsIcon}>{icon}</Text>
      <View style={styles.settingsInfo}>
        <Text style={[styles.settingsTitle, { color: colors.textPrimary }]}>
          {title}
        </Text>
        {value && (
          <Text style={[styles.settingsValue, { color: colors.textSecondary }]}>
            {value}
          </Text>
        )}
      </View>
      {rightComponent}
      {!rightComponent && onPress && showArrow && (
        <Text style={[styles.arrow, { color: colors.textLight }]}>→</Text>
      )}
    </TouchableOpacity>
  );

  const SectionTitle: React.FC<{ title: string }> = ({ title }) => (
    <Text style={[styles.sectionTitle, { color: colors.textSecondary }]}>
      {title}
    </Text>
  );

  return (
    <View style={[styles.container, { backgroundColor: colors.bgGray }]}>
      <ScrollView
        contentContainerStyle={[
          styles.scrollContent,
          { paddingTop: insets.top + Spacing.md },
        ]}
        showsVerticalScrollIndicator={false}
      >
        {/* Header */}
        <Text style={[styles.title, { color: colors.textPrimary }]}>
          {t.settings.title}
        </Text>

        {/* Account Section */}
        <SectionTitle title={t.settings.account} />
        <Card style={styles.section}>
          <SettingsItem
            icon="👤"
            title={t.settings.profile}
            value={user?.email || 'Not signed in'}
            onPress={() => navigation.navigate('Profile')}
          />
          <View style={[styles.divider, { backgroundColor: colors.border }]} />
          <SettingsItem
            icon="🔒"
            title={t.settings.changePassword}
            onPress={() => {}}
          />
          <View style={[styles.divider, { backgroundColor: colors.border }]} />
          <SettingsItem
            icon="🚪"
            title={t.auth.logout}
            onPress={handleLogout}
            showArrow={false}
          />
        </Card>

        {/* Preferences Section */}
        <SectionTitle title={t.settings.preferences} />
        <Card style={styles.section}>
          <SettingsItem
            icon="🌙"
            title={t.settings.darkMode}
            rightComponent={
              <Switch
                value={isDark}
                onValueChange={toggleTheme}
                trackColor={{ false: colors.border, true: colors.primary }}
                thumbColor="#FFFFFF"
              />
            }
          />
          <View style={[styles.divider, { backgroundColor: colors.border }]} />
          <SettingsItem
            icon="🌐"
            title={t.settings.language}
            value={LANGUAGES.find(l => l.code === language)?.nativeName || 'English'}
            onPress={handleLanguageChange}
          />
          <View style={[styles.divider, { backgroundColor: colors.border }]} />
          <SettingsItem
            icon="🔔"
            title={t.settings.notifications}
            rightComponent={
              <Switch
                value={notifications}
                onValueChange={setNotifications}
                trackColor={{ false: colors.border, true: colors.primary }}
                thumbColor="#FFFFFF"
              />
            }
          />
        </Card>

        {/* About Section */}
        <SectionTitle title={t.settings.about} />
        <Card style={styles.section}>
          <SettingsItem
            icon="ℹ️"
            title={t.settings.version}
            value="1.0.0"
            showArrow={false}
          />
          <View style={[styles.divider, { backgroundColor: colors.border }]} />
          <SettingsItem
            icon="⭐"
            title={t.settings.rateApp}
            onPress={() => {}}
          />
          <View style={[styles.divider, { backgroundColor: colors.border }]} />
          <SettingsItem
            icon="📧"
            title={t.settings.contactSupport}
            onPress={() => {}}
          />
          <View style={[styles.divider, { backgroundColor: colors.border }]} />
          <SettingsItem
            icon="📋"
            title={t.settings.privacyPolicy}
            onPress={() => {}}
          />
          <View style={[styles.divider, { backgroundColor: colors.border }]} />
          <SettingsItem
            icon="📋"
            title={t.settings.termsOfService}
            onPress={() => {}}
          />
        </Card>

        {/* Storage Section */}
        <SectionTitle title={t.settings.storage} />
        <Card style={styles.section}>
          <View style={styles.storageInfo}>
            <Text style={[styles.storageText, { color: colors.textPrimary }]}>
              {t.settings.used || 'Used'}: {usedMB} MB / {limitMB} MB
            </Text>
            <View style={[styles.storageBar, { backgroundColor: colors.border }]}>
              <View
                style={[
                  styles.storageProgress,
                  { backgroundColor: colors.primary, width: `${usagePercent}%` },
                ]}
              />
            </View>
            {!isPro && (
              <Text style={[styles.upgradeHint, { color: colors.textSecondary }]}>
                {t.subscription?.upgradeForMore || 'Upgrade to Pro for unlimited storage'}
              </Text>
            )}
          </View>
          <TouchableOpacity
            style={[styles.clearButton, { borderColor: colors.error }]}
            onPress={handleClearCache}
          >
            <Text style={[styles.clearButtonText, { color: colors.error }]}>
              {t.settings.clearCache}
            </Text>
          </TouchableOpacity>
        </Card>

        {/* Footer */}
        <View style={styles.footer}>
          <Text style={[styles.footerText, { color: colors.textLight }]}>
            PDF Master Pro v1.0.0
          </Text>
          <Text style={[styles.footerText, { color: colors.textLight }]}>
            Made with ❤️ for PDF lovers
          </Text>
        </View>

        {/* Bottom Padding */}
        <View style={{ height: insets.bottom + 100 }} />
      </ScrollView>
    </View>
  );
};

